const webhookItem = $('Webhook').first();
const config = $input.first().json;
const headers = webhookItem.json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';

function reject(errorCode) {
  return [{ json: { valid: false, errorCode } }];
}

function sha256HexBytes(bytes) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
  const len = bytes.length;
  const bitLen = len * 8;
  const paddedLen = Math.ceil((len + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLen);
  padded.set(bytes);
  padded[len] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(paddedLen - 8, Math.floor(bitLen / 0x100000000), false);
  view.setUint32(paddedLen - 4, bitLen >>> 0, false);
  const w = new Uint32Array(64);
  for (let offset = 0; offset < paddedLen; offset += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(offset + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = ((w[i - 15] >>> 7) | (w[i - 15] << 25)) ^ ((w[i - 15] >>> 18) | (w[i - 15] << 14)) ^ (w[i - 15] >>> 3);
      const s1 = ((w[i - 2] >>> 17) | (w[i - 2] << 15)) ^ ((w[i - 2] >>> 19) | (w[i - 2] << 13)) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
    for (let i = 0; i < 64; i++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = b; b = a; a = (temp1 + temp2) >>> 0;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0; h5 = (h5 + f) >>> 0; h6 = (h6 + g) >>> 0; h7 = (h7 + h) >>> 0;
  }
  return [h0, h1, h2, h3, h4, h5, h6, h7].map((v) => v.toString(16).padStart(8, '0')).join('');
}

if (!authHeader.startsWith('Bearer ')) {
  return reject('MISSING_BEARER_TOKEN');
}

const token = authHeader.slice(7).trim();
const parts = token.split('.');
if (parts.length !== 3) {
  return reject('MALFORMED_JWT');
}

let claims;
try {
  const padded = parts[1].replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (parts[1].length % 4)) % 4);
  claims = JSON.parse(Buffer.from(padded, 'base64').toString('utf8'));
} catch {
  return reject('INVALID_JWT_PAYLOAD');
}

if (
  claims.iss !== config.expectedIss ||
  claims.aud !== config.expectedAud ||
  typeof claims.jti !== 'string' ||
  claims.jti.trim().length === 0 ||
  typeof claims.bodySha256 !== 'string'
) {
  return reject('INVALID_JWT_CLAIMS');
}

let rawBytes;
if (webhookItem.binary && webhookItem.binary.data && typeof webhookItem.binary.data.data === 'string') {
  rawBytes = Buffer.from(webhookItem.binary.data.data, 'base64');
} else if ($input.first().binary && $input.first().binary.data) {
  rawBytes = await this.helpers.getBinaryDataBuffer(0, 'data');
} else {
  rawBytes = Buffer.from(JSON.stringify(webhookItem.json.body ?? {}), 'utf8');
}

const computedHash = sha256HexBytes(rawBytes);
if (computedHash !== claims.bodySha256) {
  return reject('BODY_HASH_MISMATCH');
}

let payload;
try {
  payload = JSON.parse(rawBytes.toString('utf8'));
} catch {
  return reject('INVALID_JSON_BODY');
}

if (!payload || typeof payload.recipientEmail !== 'string' || !payload.recipientEmail.trim()) {
  return reject('MISSING_RECIPIENT');
}

const listingName = String(payload.listingName || 'Listing');
const startDate = String(payload.startDate || '');
const endDate = String(payload.endDate || '');
const counterparty = String(payload.counterpartyName || 'A neighbor');
const appUrl = String(payload.appUrl || 'http://localhost:3000');

const templates = {
  loan_requested: {
    subject: `[${config.appName}] New Loan request for ${listingName}`,
    text: `Hi ${payload.recipientName || 'Neighbor'},\n\n${counterparty} requested to borrow "${listingName}" from ${startDate} to ${endDate}.\n${payload.note ? `Note: ${payload.note}\n` : ''}\nReview the request in ${config.appName}: ${appUrl}/incoming-requests\n`,
  },
  loan_approved: {
    subject: `[${config.appName}] Loan approved: ${listingName}`,
    text: `Hi ${payload.recipientName || 'Neighbor'},\n\n${counterparty} approved your Loan for "${listingName}" (${startDate} to ${endDate}).\n\nView details: ${appUrl}/my-requests\n`,
  },
  loan_declined: {
    subject: `[${config.appName}] Loan declined: ${listingName}`,
    text: `Hi ${payload.recipientName || 'Neighbor'},\n\nYour Loan request for "${listingName}" (${startDate} to ${endDate}) was declined.\n${payload.decisionReason ? `Reason: ${payload.decisionReason}\n` : ''}\nBrowse other listings: ${appUrl}/listings\n`,
  },
  loan_cancelled: {
    subject: `[${config.appName}] Loan cancelled: ${listingName}`,
    text: `Hi ${payload.recipientName || 'Neighbor'},\n\nThe Loan for "${listingName}" (${startDate} to ${endDate}) was cancelled by ${counterparty}.\n\nView details: ${appUrl}/listings\n`,
  },
  loan_returned: {
    subject: `[${config.appName}] Loan marked returned: ${listingName}`,
    text: `Hi ${payload.recipientName || 'Neighbor'},\n\n${counterparty} marked your Loan for "${listingName}" (${startDate} to ${endDate}) as returned. Thanks for sharing!\n`,
  },
};

const template = templates[payload.eventType] || {
  subject: `[${config.appName}] Loan update: ${listingName}`,
  text: `Hi ${payload.recipientName || 'Neighbor'},\n\nThere is an update on your Loan for "${listingName}" (${startDate} to ${endDate}).\n`,
};

return [
  {
    json: {
      valid: true,
      jti: claims.jti,
      eventId: String(payload.eventId || claims.jti),
      eventType: String(payload.eventType || 'loan_update'),
      recipientEmail: payload.recipientEmail.trim(),
      fromEmail: config.fromEmail,
      subject: template.subject,
      text: template.text,
    },
  },
];
